/* ---------- responsive button feedback ---------- */
button:not(:disabled){touch-action:manipulation}
button:not(:disabled):hover{filter:brightness(1.06)}
button:not(:disabled):active{filter:brightness(1.12);transform:scale(.97)}
button.button-feedback{animation:button-feedback .26s cubic-bezier(.2,.8,.25,1)}
@keyframes button-feedback{
  0%{transform:scale(1);filter:brightness(1)}
  38%{transform:scale(.94);filter:brightness(1.14)}
  100%{transform:scale(1);filter:brightness(1)}
}
@media(prefers-reduced-motion:reduce){
  button.button-feedback{animation:none}
}

