import base64, json, os, socket, struct, subprocess, tempfile, time, urllib.request

PORT = 9223
profile = tempfile.mkdtemp(prefix='kk-chrome-')
proc = subprocess.Popen(['/usr/bin/chromium', '--no-sandbox', '--disable-gpu', '--headless=new', '--remote-allow-origins=*', f'--remote-debugging-port={PORT}', f'--user-data-dir={profile}', 'about:blank'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

def http_json(url):
    with urllib.request.urlopen(url, timeout=5) as r: return json.load(r)

try:
    for _ in range(80):
        try:
            targets = http_json(f'http://127.0.0.1:{PORT}/json')
            break
        except Exception: time.sleep(.15)
    target = next(t for t in targets if t['type'] == 'page')
    wsurl = target['webSocketDebuggerUrl']
    from urllib.parse import urlparse
    u=urlparse(wsurl); s=socket.create_connection((u.hostname,u.port),timeout=10)
    key=base64.b64encode(os.urandom(16)).decode()
    s.sendall(f'GET {u.path} HTTP/1.1\r\nHost: {u.hostname}:{u.port}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\nOrigin: http://localhost\r\n\r\n'.encode())
    response=b''
    while b'\r\n\r\n' not in response: response += s.recv(4096)
    assert b'101' in response.split(b'\r\n',1)[0], response[:200]
    pending=b''
    seq=0
    def send(obj):
        global seq
        payload=json.dumps(obj).encode(); mask=os.urandom(4)
        n=len(payload)
        head=bytes([0x81, (0x80|n) if n<126 else 0x80|126])
        if n>=126: head+=struct.pack('!H',n)
        payload=bytes(c ^ mask[i%4] for i,c in enumerate(payload))
        s.sendall(head+mask+payload)
    def recv_message():
        global pending
        while True:
            while len(pending)<2: pending+=s.recv(65536)
            b1,b2=pending[0],pending[1]; n=b2&127; idx=2
            if n==126:
                while len(pending)<4: pending+=s.recv(65536)
                n=struct.unpack('!H',pending[2:4])[0]; idx=4
            elif n==127:
                while len(pending)<10: pending+=s.recv(65536)
                n=struct.unpack('!Q',pending[2:10])[0]; idx=10
            mask=None
            if b2&128:
                while len(pending)<idx+4: pending+=s.recv(65536)
                mask=pending[idx:idx+4];idx+=4
            while len(pending)<idx+n: pending+=s.recv(65536)
            data=pending[idx:idx+n];pending=pending[idx+n:]
            if mask: data=bytes(c^mask[i%4] for i,c in enumerate(data))
            if b1&15==8: raise RuntimeError('websocket closed')
            if b1&15==9:
                s.sendall(bytes([0x8a,len(data)])+data);continue
            if b1&15==1: return json.loads(data)
    def cmd(method, params=None):
        global seq
        seq+=1; my=seq
        send({'id':my,'method':method,'params':params or {}})
        while True:
            m=recv_message()
            if m.get('id')==my:
                if 'error' in m: raise RuntimeError(m['error'])
                return m.get('result',{})
    def evaluate(expr):
        result=cmd('Runtime.evaluate',{'expression':expr,'returnByValue':True,'awaitPromise':True})
        if result.get('exceptionDetails'): raise RuntimeError(result['exceptionDetails'])
        return result.get('result',{}).get('value')
    cmd('Page.enable');cmd('Runtime.enable')
    cmd('Page.navigate',{'url':'http://127.0.0.1:8765/'})
    for _ in range(100):
        try:
            if evaluate("document.readyState === 'complete' && !!window.KK?.game"): break
        except Exception: pass
        time.sleep(.1)
    evaluate("document.querySelector('#cityNameInput').value='QA City'; document.querySelector('#newGameBtn').click()")
    for _ in range(60):
        started=evaluate("!document.querySelector('#startScreen').classList.contains('visible') && !!KK.game.state")
        if started: break
        time.sleep(.1)
    assert started, 'new game did not start'
    desktop=evaluate("(() => { const p=document.querySelector('#sidePanel'),b=document.querySelector('#sideBtn'); b.click(); const opened=!p.classList.contains('hidden')&&b.getAttribute('aria-expanded')==='true'; document.querySelector('#sideClose').click(); const closed=p.classList.contains('hidden')&&b.getAttribute('aria-expanded')==='false'; b.click(); const reopened=!p.classList.contains('hidden')&&b.getAttribute('aria-expanded')==='true'; b.click(); document.querySelector('#pauseBtn').click(); const paused=KK.game.state.paused; document.querySelector('#settingsBtn').click(); const settings=!!document.querySelector('.settings-modal')&&!KK.game.state.modalPause&&KK.game.state.paused; document.querySelector('#speedGroup [data-speed=\"2\"]').click(); const speed=KK.game.state.speed===2&&KK.game.state.paused; document.querySelector('#periodSelect').value='month'; document.querySelector('#periodSelect').dispatchEvent(new Event('change',{bubbles:true})); const period=KK.game.state.period==='month'&&KK.game.state.paused; document.querySelector('#settingsSoundBtn').click(); const sound=document.querySelector('#settingsSoundBtn').getAttribute('aria-pressed')==='false'; document.querySelector('#settingsThemeBtn').click(); const theme=document.documentElement.dataset.theme==='dark'; document.querySelector('.modal-x').click(); return {opened,closed,reopened,settings,speed,period,sound,theme,dateVisible:!!document.querySelector('#dateLabel').getClientRects().length,pauseVisible:!!document.querySelector('#pauseBtn').getClientRects().length}; })()")
    assert all(desktop[k] for k in ['opened','closed','reopened','settings','speed','period','sound','theme','dateVisible','pauseVisible']), desktop
    cmd('Emulation.setDeviceMetricsOverride',{'width':390,'height':844,'deviceScaleFactor':1,'mobile':True})
    mobile=evaluate("(() => { const p=document.querySelector('#sidePanel'),b=document.querySelector('#sideBtn'); b.click(); const opened=p.classList.contains('mobile-open')&&b.getAttribute('aria-expanded')==='true'&&getComputedStyle(p).display!=='none'; document.querySelector('#sideClose').click(); const closed=!p.classList.contains('mobile-open')&&b.getAttribute('aria-expanded')==='false'; b.click(); const reopened=p.classList.contains('mobile-open')&&b.getAttribute('aria-expanded')==='true'&&getComputedStyle(p).display!=='none'; document.querySelector('#settingsBtn').click(); const settings=!!document.querySelector('.settings-modal'); return {opened,closed,reopened,settings,dateVisible:!!document.querySelector('#dateLabel').getClientRects().length,pauseVisible:!!document.querySelector('#pauseBtn').getClientRects().length,viewport:innerWidth}; })()")
    assert all(mobile[k] for k in ['opened','closed','reopened','settings','dateVisible','pauseVisible']), mobile
    print(json.dumps({'desktop':desktop,'mobile':mobile},indent=2))
finally:
    proc.terminate()
    try: proc.wait(timeout=5)
    except subprocess.TimeoutExpired: proc.kill()

